import pandas as pd, numpy as np, json, math,itertools
d=pd.read_csv(\"respondents.csv\")
def base(x):
 w=x.wt_design
 return dict(n=len(x),w=w.sum(),ess=w.sum()**2/(w*w).sum())
def mean(x,y):
 w=x.wt_design.to_numpy(); y=np.asarray(y,float); q=(w*y).sum()/w.sum(); v=len(x)/(len(x)-1)*(w*w*(y-q)**2).sum()/w.sum()**2
 return dict(est=q,var=v,ci=[q-1.95996398454*np.sqrt(v),q+1.95996398454*np.sqrt(v)])
def dist(x,col,vals):
 return {str(v):float(x.loc[x[col]==v,\"wt_design\"].sum()/x.wt_design.sum()) for v in vals}
def proxy(q,k):
 return dict(est=k*q[\"est\"],ci=[k*q[\"est\"]-1.95996398454*abs(k)*np.sqrt(q[\"var\"]),k*q[\"est\"]+1.95996398454*abs(k)*np.sqrt(q[\"var\"])])
arms={}; qs={}; q0s={}
baseline=[\"age_band\",\"household_children\",\"budget_band\",\"meal_planning_role\",\"weekday_time_pressure_5\",\"current_planning_method\",\"digital_confidence_5\",\"plan_ahead_days_7\",\"subscription_spend_band\",\"household_size_band\",\"design_stratum\",\"time_pressed_family\"]
for p,x in d.groupby(\"assigned_price_gbp\"):
 p=int(p); v=x[x.intent_5.isin([1,2,3,4,5])]; m=x[x.postprice_responded==1]
 q=mean(v,v.intent_5.isin([4,5])); q0=mean(x,x.intent_5.isin([4,5])); qs[p]=q;q0s[p]=q0
 missing={}
 for label,mask in [(\"exit\",x.postprice_responded==0)]+[(str(c),x.intent_5==c) for c in [97,98,99]]:
  missing[label]=dict(n=int(mask.sum()),share=x.loc[mask,\"wt_design\"].sum()/x.wt_design.sum())
 arms[p]=dict(assigned=base(x),module=base(m),valid=base(v),intent_distribution=dist(v,\"intent_5\",[1,2,3,4,5]),qv=q,q0=q0,missing=missing,bounds=[q0[\"est\"],q0[\"est\"]+1-v.wt_design.sum()/x.wt_design.sum()],Gv=proxy(q,p),G0=proxy(q0,p),Cv={c:proxy(q,p-c) for c in [.5,2,3]},C0={c:proxy(q0,p-c) for c in [.5,2,3]},baseline={col:dist(x,col,sorted(d[col].unique())) for col in baseline})
def contrasts(qs, costs):
 out=[]
 for c in costs:
  for a,b in itertools.combinations([4,7,10,13],2):
   ka,kb=(1,1) if c is None else (a-c,b-c)
   dif=ka*qs[a][\"est\"]-kb*qs[b][\"est\"];se=np.sqrt(ka**2*qs[a][\"var\"]+kb**2*qs[b][\"var\"])
   out.append(dict(a=a,b=b,c=c,diff=dif,ci=[dif-1.95996398454*se,dif+1.95996398454*se],p=math.erfc(abs(dif/se)/np.sqrt(2))))
 order=sorted(range(len(out)),key=lambda i:out[i][\"p\"]);prev=0
 for j,i in enumerate(order):
  prev=max(prev,min(1,(len(out)-j)*out[i][\"p\"]));out[i][\"holm\"]=prev
 return out
aud={};tests=[]
for p in [7,10]:
 cells={}
 for g in [0,1,97]:
  x=d[(d.assigned_price_gbp==p)&(d.time_pressed_family==g)];v=x[x.intent_5.isin([1,2,3,4,5])]
  cells[g]=dict(eligible=base(x),valid=base(v))
  if len(v)>=40:cells[g][\"q\"]=mean(v,v.intent_5.isin([4,5]))
 aud[p]=cells
 a,b=cells[1][\"q\"],cells[0][\"q\"];dif=a[\"est\"]-b[\"est\"];se=np.sqrt(a[\"var\"]+b[\"var\"])
 tests.append(dict(price=p,diff=dif,ci=[dif-1.95996398454*se,dif+1.95996398454*se],p=math.erfc(abs(dif/se)/np.sqrt(2))))
 order=sorted(range(len(tests)),key=lambda i:tests[i][\"p\"])
prev=0
for j,i in enumerate(order):
 prev=max(prev,min(1,(2-j)*tests[i][\"p\"]));tests[i][\"holm\"]=prev
niche={}
for p,x in d[(d.age_band.isin([3,4]))&(d.budget_band==3)&(d.current_planning_method==4)].groupby(\"assigned_price_gbp\"):
 niche[int(p)]={\"eligible\":base(x),\"valid\":base(x[x.intent_5.isin([1,2,3,4,5])]),\"status\":\"suppressed\"}
out={\"arms\":arms,\"P1\":contrasts(qs,[None]),\"P2\":contrasts(q0s,[None]),\"P3\":contrasts(qs,[0]),\"P4\":contrasts(qs,[.5,2,3]),\"audience\":aud,\"P5\":tests,\"niche\":niche}
def clean(o):
 if isinstance(o,dict):return {str(k):clean(v) for k,v in o.items()}
 if isinstance(o,list):return [clean(v) for v in o]
 if isinstance(o,(float,np.floating)):return round(float(o),6)
 if isinstance(o,np.integer):return int(o)
 return o
print(json.dumps(clean(out)))
'"

